    private ConfiguracoesNfe configuracao;

    @BeforeEach
    void setUp() {
        configuracao = new ConfiguracoesNfe();
        configuracao.setEstado(EstadosEnum.SP);
        configuracao.setAmbiente(AmbienteEnum.HOMOLOGACAO);
        configuracao.setZoneId(ZoneId.of("UTC"));
    }

    @Test
    void testMontaCancelamento_SingleEvent() throws NfeException {
        Evento evento = new Evento();
        evento.setChave("41191234567890123456789000012345678901234567");
        evento.setCpf("12345678901");
        evento.setDataEvento(ZonedDateTime.now(configuracao.getZoneId()));
        evento.setProtocolo("123456789012345");
        evento.setMotivo("Erro de emissão");

        List<Evento> eventos = Collections.singletonList(evento);

        TEnvEvento result = CancelamentoUtil.montaCancelamento(eventos, configuracao);

        assertNotNull(result);
        assertEquals("1", result.getIdLote());
        assertEquals(ConstantesUtil.VERSAO.EVENTO_CANCELAMENTO, result.getVersao());
        assertNotNull(result.getEvento());
        assertEquals(1, result.getEvento().size());

        TEvento tEvento = result.getEvento().get(0);
        TEvento.InfEvento infEvento = tEvento.getInfEvento();

        assertEquals("ID" + EventosEnum.CANCELAMENTO.getCodigo() + evento.getChave() + "01", infEvento.getId());
        assertEquals(evento.getChave(), infEvento.getChNFe());
        assertEquals(String.valueOf(EstadosEnum.SP.getCodigoUF()), infEvento.getCOrgao());
        assertEquals(AmbienteEnum.HOMOLOGACAO.getCodigo(), infEvento.getTpAmb());
        assertEquals(evento.getCpf(), infEvento.getCPF());
        assertNull(infEvento.getCNPJ());
        assertEquals(EventosEnum.CANCELAMENTO.getCodigo(), infEvento.getTpEvento());
        assertEquals("1", infEvento.getNSeqEvento());
        assertEquals(ConstantesUtil.VERSAO.EVENTO_CANCELAMENTO, infEvento.getVerEvento());

        TEvento.InfEvento.DetEvento detEvento = infEvento.getDetEvento();
        assertEquals(ConstantesUtil.VERSAO.EVENTO_CANCELAMENTO, detEvento.getVersao());
        assertEquals("Cancelamento", detEvento.getDescEvento());
        assertEquals(evento.getProtocolo(), detEvento.getNProt());
        assertEquals(evento.getMotivo(), detEvento.getXJust());
    }

    @Test
    void testMontaCancelamento_EventWithCnpj() throws NfeException {
        Evento evento = new Evento();
        evento.setChave("41191234567890123456789000012345678901234567");
        evento.setCnpj("12345678000190");
        evento.setDataEvento(ZonedDateTime.now(configuracao.getZoneId()));
        evento.setProtocolo("123456789012345");
        evento.setMotivo("Cancelamento por erro");

        List<Evento> eventos = Collections.singletonList(evento);

        TEnvEvento result = CancelamentoUtil.montaCancelamento(eventos, configuracao);

        assertNotNull(result);
        TEvento tEvento = result.getEvento().get(0);
        TEvento.InfEvento infEvento = tEvento.getInfEvento();

        assertEquals(evento.getCnpj(), infEvento.getCNPJ());
        assertNull(infEvento.getCPF());
    }

    @Test
    void testMontaCancelamento_MultipleEvents() throws NfeException {
        Evento evento1 = new Evento();
        evento1.setChave("41191234567890123456789000012345678901234567");
        evento1.setCpf("12345678901");
        evento1.setDataEvento(ZonedDateTime.now(configuracao.getZoneId()));
        evento1.setProtocolo("123456789012345");
        evento1.setMotivo("Motivo 1");

        Evento evento2 = new Evento();
        evento2.setChave("41191234567890123456789000012345678901234568");
        evento2.setCpf("98765432100");
        evento2.setDataEvento(ZonedDateTime.now(configuracao.getZoneId()));
        evento2.setProtocolo("987654321098765");
        evento2.setMotivo("Motivo 2");

        List<Evento> eventos = List.of(evento1, evento2);

        TEnvEvento result = CancelamentoUtil.montaCancelamento(eventos, configuracao);

        assertNotNull(result);
        assertEquals(2, result.getEvento().size());

        TEvento.InfEvento infEvento1 = result.getEvento().get(0).getInfEvento();
        assertEquals(evento1.getChave(), infEvento1.getChNFe());
        assertEquals(evento1.getCpf(), infEvento1.getCPF());

        TEvento.InfEvento infEvento2 = result.getEvento().get(1).getInfEvento();
        assertEquals(evento2.getChave(), infEvento2.getChNFe());
        assertEquals(evento2.getCpf(), infEvento2.getCPF());
    }

    @Test
    void testMontaCancelamento_Maximum20Events() throws NfeException {
        List<Evento> eventos = Collections.nCopies(20, createMockEvent());

        TEnvEvento result = CancelamentoUtil.montaCancelamento(eventos, configuracao);

        assertNotNull(result);
        assertEquals(20, result.getEvento().size());
    }

    @Test
    void testMontaCancelamento_MoreThan20Events() {
        List<Evento> eventos = Collections.nCopies(21, createMockEvent());

        NfeException exception = assertThrows(NfeException.class, () -> {
            CancelamentoUtil.montaCancelamento(eventos, configuracao);
        });

        assertEquals("Podem ser enviados no máximo 20 eventos no Lote.", exception.getMessage());
    }

    private Evento createMockEvent() {
        Evento evento = new Evento();
        evento.setChave("41191234567890123456789000012345678901234567");
        evento.setCpf("12345678901");
        evento.setDataEvento(ZonedDateTime.now(ZoneId.of("UTC")));
        evento.setProtocolo("123456789012345");
        evento.setMotivo("Teste");
        return evento;
    }
}

