class GenerateReportTests {

    private ValidationReport validationReport;

    @BeforeEach
    void setUp() {
        validationReport = new ValidationReport();
    }

    @Test
    void testGenerateReportFullCompatibility() {
        validationReport.arrayDetected = false;
        validationReport.extraFields = new ArrayList<>();
        validationReport.missingFields = new ArrayList<>();
        validationReport.typeErrors = new HashMap<>();
        validationReport.strictConversionSuccess = true;
        validationReport.strictConversionError = null;

        String result = validationReport.generateReport();

        assertTrue(result.contains("=== RELATORIO DE VALIDACAO ==="));
        assertTrue(result.contains("ESTRUTURA 100% COMPATIVEL"));
        assertTrue(result.contains("Nenhum campo extra no JSON"));
        assertTrue(result.contains("Nenhum campo faltando"));
        assertTrue(result.contains("Todos os tipos estao corretos"));
        assertTrue(result.contains("Conversao estrita: SUCESSO"));
        assertFalse(result.contains("ATENCAO:"));
        assertFalse(result.contains("ERRO:"));
    }

    @Test
    void testGenerateReportWithExtraFields() {
        validationReport.arrayDetected = false;
        List<String> extras = new ArrayList<>();
        extras.add("unknownField1");
        extras.add("unknownField2");
        validationReport.extraFields = extras;
        validationReport.missingFields = new ArrayList<>();
        validationReport.typeErrors = new HashMap<>();
        validationReport.strictConversionSuccess = true;
        validationReport.strictConversionError = null;

        String result = validationReport.generateReport();

        assertTrue(result.contains("ATENCAO: Campos EXTRAS no JSON (nao mapeados no DTO):"));
        assertTrue(result.contains("  - unknownField1"));
        assertTrue(result.contains("  - unknownField2"));
        assertFalse(result.contains("ESTRUTURA 100% COMPATIVEL"));
    }

    @Test
    void testGenerateReportWithMissingFields() {
        validationReport.arrayDetected = false;
        validationReport.extraFields = new ArrayList<>();
        List<String> missing = new ArrayList<>();
        missing.add("requiredField1");
        missing.add("requiredField2");
        validationReport.missingFields = missing;
        validationReport.typeErrors = new HashMap<>();
        validationReport.strictConversionSuccess = true;
        validationReport.strictConversionError = null;

        String result = validationReport.generateReport();

        assertTrue(result.contains("ATENCAO: Campos FALTANDO no JSON (esperados no DTO):"));
        assertTrue(result.contains("  - requiredField1"));
        assertTrue(result.contains("  - requiredField2"));
        assertFalse(result.contains("ESTRUTURA 100% COMPATIVEL"));
    }

    @Test
    void testGenerateReportWithTypeErrors() {
        validationReport.arrayDetected = false;
        validationReport.extraFields = new ArrayList<>();
        validationReport.missingFields = new ArrayList<>();
        Map<String, String> errors = new HashMap<>();
        errors.put("fieldA", "Esperado Integer, encontrado String");
        errors.put("fieldB", "Esperado Boolean, encontrado Double");
        validationReport.typeErrors = errors;
        validationReport.strictConversionSuccess = true;
        validationReport.strictConversionError = null;

        String result = validationReport.generateReport();

        assertTrue(result.contains("ERRO: Incompatibilidade de tipos:"));
        assertTrue(result.contains("  - fieldA: Esperado Integer, encontrado String"));
        assertTrue(result.contains("  - fieldB: Esperado Boolean, encontrado Double"));
        assertFalse(result.contains("ESTRUTURA 100% COMPATIVEL"));
    }

    @Test
    void testGenerateReportWithAllValidationErrors() {
        validationReport.arrayDetected = false;

        List<String> extras = new ArrayList<>();
        extras.add("extra");
        validationReport.extraFields = extras;

        List<String> missing = new ArrayList<>();
        missing.add("missing");
        validationReport.missingFields = missing;

        Map<String, String> errors = new HashMap<>();
        errors.put("typeErr", "Type mismatch");
        validationReport.typeErrors = errors;

        validationReport.strictConversionSuccess = false;
        validationReport.strictConversionError = "Parse exception";

        String result = validationReport.generateReport();

        assertTrue(result.contains("ATENCAO: Campos EXTRAS no JSON"));
        assertTrue(result.contains("ATENCAO: Campos FALTANDO no JSON"));
        assertTrue(result.contains("ERRO: Incompatibilidade de tipos"));
        assertTrue(result.contains("Conversao estrita: FALHOU"));
        assertTrue(result.contains("  Erro: Parse exception"));
        assertFalse(result.contains("ESTRUTURA 100% COMPATIVEL"));
    }

    @Test
    void testGenerateReportWithArrayDetected() {
        validationReport.arrayDetected = true;
        validationReport.arraySize = 5;
        validationReport.extraFields = new ArrayList<>();
        validationReport.missingFields = new ArrayList<>();
        validationReport.typeErrors = new HashMap<>();
        validationReport.strictConversionSuccess = true;
        validationReport.strictConversionError = null;

        String result = validationReport.generateReport();

        assertTrue(result.contains("Array detectado com 5 elemento(s)"));
        assertTrue(result.contains("Validacao realizada no primeiro elemento"));
    }

    @Test
    void testGenerateReportStrictConversionFailed() {
        validationReport.arrayDetected = false;
        validationReport.extraFields = new ArrayList<>();
        validationReport.missingFields = new ArrayList<>();
        validationReport.typeErrors = new HashMap<>();
        validationReport.strictConversionSuccess = false;
        validationReport.strictConversionError = "IllegalStateException occurred";

        String result = validationReport.generateReport();

        assertTrue(result.contains("Conversao estrita: FALHOU"));
        assertTrue(result.contains("  Erro: IllegalStateException occurred"));
        assertFalse(result.contains("Conversao estrita: SUCESSO"));
    }
}

